INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:عتو:jawhari_sihah', 'عتو', '7389077f267092d35c0f5c8129', 'وعَتا الشيخ يَعْتُو عُتِيًّا وعِتِيًّا: كبر وولى', 'the old man grew very old', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_f14574df2069d538', '4796', 6, 'blk_sih_081bfd30780f2af3', 0, NULL, 'Marker: verb gloss. Reading: old age. Differs from the main reading (arrogance, going too far).', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:عتو:raghib_mufradat', 'عتو', '7389077f267092d35c0f5c8129', 'العُتُوُّ: النبوّ عن الطاعة', 'turning away from obedience', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_c3ee7cd8fafb674b', '546', 1, 'blk_mfr_7087d1013330091e', 0, NULL, 'Marker: head gloss. Reading: refusing obedience.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:عتو:ibn_manzur_lisan_arab', 'عتو', '7389077f267092d35c0f5c8129', 'عَتَا يَعْتُو عُتُوّاً وعِتِيّاً: اسْتَكْبَرَ وجاوَزَ الحَدَّ', 'he was proud and went past the limit', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_db106b14ae55e46a', '862', 2, 'blk_lsn_5fffdb320b73081a', 0, NULL, 'Marker: head gloss. Reading: pride, going too far.', 'high', 'active');
