INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:عتو:zabidi_taj_arus', 'عتو', '7389077f267092d35c0f5c8129', 'وَهَذَا هُوَ الأصْلُ فِي البابِ: (اسْتَكْبَرَ وجاوَزَ الحَدَّ)', 'the core: he was proud, went past the limit', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_e26ce59c29ff99d1', '533', 38, 'blk_taj_a910e52cc0cc7734', 0, NULL, 'Marker: «هذا هو الأصل في الباب». Reading: pride, going too far.', 'high', 'active');
