UPDATE ar_ling_root_asl SET is_primary = CASE WHEN id = 'ASL:عتو:maqayis_lugha' THEN 1 ELSE 0 END, updated_at = datetime('now') WHERE root_norm = 'عتو' AND EXISTS (SELECT 1 FROM ar_ling_root_asl WHERE id = 'ASL:عتو:maqayis_lugha' AND status <> 'rejected');
