INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:عثر:khalil_kitab_ayn', 'عثر', 'd70a4388fca8f8964c037f24b2', 'وعثر الفرس عِثاراً إذا أصاب قوائمه شيء، فيُصرع أو يَتَتَعْتَعُ', 'horse''s legs hit something; it falls or staggers', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_8e75df9dd27b4fb0', '460', NULL, 'blk_kay_8655dd39f10e1f1e', 0, NULL, 'Marker: «إذا» head gloss. Reading: stumbling. Primary: stumbling — 9 of 10 books (al-Khalīl blk_kay_8655dd39f10e1f1e; Ibn Durayd blk_jam_e7c1ba97cf0ae6fa; al-Jawharī blk_sih_f0a934f553597bf7; al-Rāghib blk_mfr_c9a31210bcd633bd; Lisān blk_lsn_878689385b3fd69d; al-Miṣbāḥ blk_msb_17bae1ecdc438853; al-Qāmūs blk_qms_9ddb4e8f13a9aeea; Tāj blk_taj_cfc4d1231afdad09; Lane blk_lane_6d665e60029c9a55). Other readings: coming upon: Ibn Fāris · dust: Ibn Fāris.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:عثر:ibn_durayd_jamharat_lugha', 'عثر', 'd70a4388fca8f8964c037f24b2', 'والعثر: الكبو', 'tripping and falling', 'ابن دريد', 'Ibn Durayd, al-Jamhara', 321, 'ibn_durayd_jamharat_lugha', 're_jam_45d21dbfefbdcac3', '385', NULL, 'blk_jam_e7c1ba97cf0ae6fa', 0, NULL, 'Marker: head gloss. Reading: stumbling.', 'high', 'active');
