INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:عثر:raghib_mufradat', 'عثر', 'd70a4388fca8f8964c037f24b2', 'عَثَرَ الرّجلُ يَعْثُرُ عِثَاراً وعُثُوراً: إذا سقط، ويتجوّز به فيمن يطّلع على أمر من غير طلبه', 'he fell; also used for chancing upon something', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_1b34a6c3ebf63ce2', '546', 1, 'blk_mfr_c9a31210bcd633bd', 0, NULL, 'Marker: head gloss. Reading: falling.', 'high', 'active');
