INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:عثر:zabidi_taj_arus', 'عثر', 'd70a4388fca8f8964c037f24b2', '(عَثرَ، كضَرَبَ ونَصَرَ وعَلِمَ وكَرُمَ) يَعْثِرُ ويَعْثُرُ ويَعْثَرُ، الثالثةُ عَن اللِّحْيَانِي (عَثْراً) ، بِالْفَتْح، (وعَثِيراً) ، كأَمِير، (وعِثَاراً) ، ككِتَابٍ، (وتَعَثَّرَ) ، إِذا (كَبَا)', 'he tripped and fell', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_d2c3324004a3287f', '524', 12, 'blk_taj_cfc4d1231afdad09', 0, NULL, 'Marker: Qāmūs gloss. Reading: stumbling.', 'high', 'active');
