INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:عدو:fayyumi_misbah_munir', 'عدو', '2c702ae92e09738869ab6e4492', 'عَدَا عَلَيْهِ يَعْدُو عَدْوًا وَعُدُوًّا مِثْلُ فَلْسٍ وَفُلُوسٍ وَعُدْوَانًا وَعَدَاءً بِالْفَتْحِ وَالْمَدِّ ظَلَمَ وَتَجَاوَزَ الْحَدَّ', 'he wronged him and went past the limit', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_1cb6b83b01b285a1', '1998', NULL, 'blk_msb_976fb496c7664d4b', 0, NULL, 'Marker: head gloss. Reading: wronging, going too far.', 'high', 'active');
