INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:عدو:zabidi_taj_arus', 'عدو', '2c702ae92e09738869ab6e4492', 'مَقْصورٌ: (أَحْضَرَ) ، يكونُ مِنَّا ومِن الخَيْلِ', 'he ran; said of people and horses', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_181868cd46486d28', '5', 39, 'blk_taj_5a4926d44ed016c7', 0, NULL, 'Marker: Qāmūs gloss. Reading: running. Differs from the main reading (going past the limit).', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:عدو:lane_lexicon', 'عدو', '2c702ae92e09738869ab6e4492', 'primarily signifies Transition; [whence what here precedes;] or the going, or passing, beyond, or the exceeding, a limit', 'passing on; going past a limit', 'لين', 'E. W. Lane, Arabic-English Lexicon', NULL, 'lane_lexicon', 're_lane_af74cc33bbf2a5a5', '1976', NULL, 'blk_lane_462e0db3323963c9', 0, NULL, 'Marker: primarily. Reading: going past. Quoted from al-Rāghib via Lane.', 'high', 'active');
