INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:عذب:ibn_durayd_jamharat_lugha', 'عذب', '88d5c1497c67f6cf94499ba2ae', 'والعذب: ضد الْملح وكل مستسيغ من طَعَام أَو شراب', 'opposite of salty; any food or drink easy to swallow', 'ابن دريد', 'Ibn Durayd, al-Jamhara', 321, 'ibn_durayd_jamharat_lugha', 're_jam_319bbbe12f3aa89b', '268', NULL, 'blk_jam_4817f4d6b7fb241f', 0, NULL, 'Marker: head gloss. Reading: sweet water.', 'high', 'active');
