INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:عرج:fayyumi_misbah_munir', 'عرج', '24e1a7816e05fe0c68cc02d8be', 'عَرِجَ فِي مَشْيِهِ عَرَجًا مِنْ بَابِ تَعِبَ إذَا كَانَ مِنْ عِلَّةٍ لَازِمَةٍ فَهُوَ أَعْرَجُ', 'he limped from a lasting defect: lame', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_57487cb7ea2594da', '2008', NULL, 'blk_msb_aa4ef92f8898cb33', 0, NULL, 'Marker: head gloss. Reading: limping. Differs from the main reading (rising up).', 'high', 'active');
