INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:عرج:zabidi_taj_arus', 'عرج', '24e1a7816e05fe0c68cc02d8be', '(عَرَجَ) فِي الدَّرَجَة والسُّلَّمِ يَعْرُجُ، بالضّمّ (عُرُوجاً ومَعْرَجاً) ، بِالْفَتْح (: ارْتَقَى)', 'he climbed the stair or ladder', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_1b2d6183ab41f8ce', '94', 6, 'blk_taj_104a2cb5fc9fb1ab', 0, NULL, 'Marker: Qāmūs gloss. Reading: climbing.', 'high', 'active');
