INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:عصب:khalil_kitab_ayn', 'عصب', '035641e13b2b38f1e4a6322203', 'العَصَبُ: أطناب المفاصل الّذي يلائم بينها، وليس بالعقب', 'the cords that hold the joints together', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_2f69000e66bf205a', '298', NULL, 'blk_kay_21f993d079896122', 0, NULL, 'Marker: head gloss. Reading: sinews. Primary: sinews — 5 of 10 books (al-Khalīl blk_kay_21f993d079896122; al-Jawharī blk_sih_fd61193338f115f2; al-Rāghib blk_mfr_5441cb9388239524; al-Qāmūs blk_qms_958a87c32fd1c266; Tāj blk_taj_b50a2a5731ef5b0e). Other readings: tying, twisting tight: Ibn Durayd, Ibn Fāris, Lisān, Lane · male kin: al-Miṣbāḥ.', 'high', 'active');
