INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:عصب:zabidi_taj_arus', 'عصب', '035641e13b2b38f1e4a6322203', 'والأَعْصَابُ: (أَطْنَابُ المَفَاصِل) الَّتِي تُلَائِمُ بَينها وتَشُدُّها', 'cords that join and tie the joints', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_829aa41f78a919e9', '375', 3, 'blk_taj_b50a2a5731ef5b0e', 0, NULL, 'Marker: Qāmūs gloss. Reading: sinews.', 'high', 'active');
