INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:عصم:ibn_durayd_jamharat_lugha', 'عصم', 'eb6bf6fc4491c53d703623315a', 'واستعصم الوَعِلُ بالصخرة واعتصم، إِذا لَاذَ بهَا من الرُماة', 'the ibex sheltered at the rock from hunters', 'ابن دريد', 'Ibn Durayd, al-Jamhara', 321, 'ibn_durayd_jamharat_lugha', 're_jam_bba2a268773c7a27', '540', NULL, 'blk_jam_b092ed0c34353c49', 0, NULL, 'Marker: first gloss naming the meaning. Reading: taking shelter.', 'medium', 'active');
