INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:عضد:khalil_kitab_ayn', 'عضد', '441a9d457b2c531d3b5feb0446', 'العضد فيه ثلاث لغات: عَضُدٌ، وعُضُد، وعُضْد. وعضُدان وأعضاد، وهو من المرفق إلى الكتف', 'the upper arm, from elbow to shoulder', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_b23d8c9143bbbfd7', '249', NULL, 'blk_kay_f2e2eb2d860f572e', 0, NULL, 'Marker: head gloss. Reading: upper arm. Filed under عنش in this book. Primary: upper arm — 9 of 10 books (al-Khalīl blk_kay_f2e2eb2d860f572e; Ibn Durayd blk_jam_832e7b06c7d90642; al-Jawharī blk_sih_d371dff4aeffd031; Ibn Fāris blk_mqy_8d7964a8e88b6aaf; al-Rāghib blk_mfr_2c3676ad2febff1e; Lisān blk_lsn_86d0d81ff12f3952; al-Qāmūs blk_qms_bfb742a717822c00; Tāj blk_taj_c038d9a3043d26c1; Lane blk_lane_d039c321fa6a3f30). Other readings: cutting trees: al-Miṣbāḥ.', 'high', 'active');
