INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:عضد:zabidi_taj_arus', 'عضد', '441a9d457b2c531d3b5feb0446', 'العَضُد من الإِنسان وغيرِه: السّاعِدُ وَهُوَ (مَا بَيْنَ المِرْفَقِ إِلى الكَتِفِ)', 'the arm between elbow and shoulder', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_c61725d42810a4db', '383', 8, 'blk_taj_c038d9a3043d26c1', 0, NULL, 'Marker: Qāmūs gloss. Reading: upper arm.', 'high', 'active');
