INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:عضل:lane_lexicon', 'عضل', 'd61b61997f2527e6b6c57f6e02', 'The primary signification of العَضْلُ is The act of straitening; (O;) or preventing, withholding, or debarring; and straitening', 'first meaning: squeezing tight, holding back', 'لين', 'E. W. Lane, Arabic-English Lexicon', NULL, 'lane_lexicon', 're_lane_929ff77b41d89836', '2074', NULL, 'blk_lane_4fc3a5d9d6ad3fc2', 0, NULL, 'Marker: primary signification. Reading: holding back, tightness.', 'high', 'active');
