INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:عضو:fayyumi_misbah_munir', 'عضو', 'e928a30f443c45edc82d7f785b', 'وَالْعُضْوُ كُلُّ عَظْمٍ وَافِرٍ مِنْ الْجَسَدِ', 'any whole bone of the body', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_6d621c7c44319b47', '2058', NULL, 'blk_msb_bb278f26b9019663', 0, NULL, 'Marker: head gloss. Reading: body part. Filed under عضل in this book.', 'medium', 'active');
