INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:عكف:ibn_durayd_jamharat_lugha', 'عكف', '613e51560c551281388befb2b9', 'عَكَف يعكُف ويعكِف عَكْفاً، إِذا أَقَامَ بِالْمَكَانِ فَهُوَ عاكف', 'he stayed on in the place', 'ابن دريد', 'Ibn Durayd, al-Jamhara', 321, 'ibn_durayd_jamharat_lugha', 're_jam_bba2a268773c7a27', '540', NULL, 'blk_jam_f059778d7717c01a', 0, NULL, 'Marker: head gloss. Reading: staying. Filed under حيي in this book.', 'medium', 'active');
