INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:عكف:raghib_mufradat', 'عكف', '613e51560c551281388befb2b9', 'العُكُوفُ: الإقبال على الشيء وملازمته على سبيل التّعظيم له', 'turning to a thing and staying, out of respect', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_8760f959c46c978c', '579', 1, 'blk_mfr_43696fb646d578ca', 0, NULL, 'Marker: head gloss. Reading: keeping at.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:عكف:ibn_manzur_lisan_arab', 'عكف', '613e51560c551281388befb2b9', 'عَكَف عَلَى الشَّيْءِ يَعْكُفُ ويَعْكِفُ عَكْفاً وعُكُوفاً: أَقبل عَلَيْهِ مُواظِباً لَا يَصْرِفُ عَنْهُ وَجْهَهُ', 'he turned to it steadily, never looking away', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_2e3443618c5cd6bf', '4562', 9, 'blk_lsn_ad25f716e7c9c6cc', 0, NULL, 'Marker: head gloss. Reading: keeping at.', 'high', 'active');
